package demo; import java.util.*; public class Probe { public static String probe(int o){List<String> p=new ArrayList<>(List.of("a","b","c","d"));List<String>v=p.subList(1,3);try{switch(o){case 0:v.set(0,"x");break;case 1:v.add("y");break;case 2:v.remove(0);break;case 3:v.clear();break;case 4:v.replaceAll(x->x.toUpperCase());break;case 5:v.sort(null);break;case 6:v.add("z");p.add("q");return v.get(0);case 7:Collections.sort(v);break;}return p+"|"+v;}catch(Exception e){return e.getClass().getName();}}public static void main(String[]a){for(int i=0;i<8;i++)System.out.println(i+"="+probe(i));}}
